using UnityEngine;using UnityEditor;using System;using System.Collections.Generic;
public static class DigitalKingdomBuilder {
 [MenuItem("Editor/Digital Kingdom/Configuración de ciudad",false,2030)]public static void Open(){Selection.activeObject=DigitalKingdomSettings.Current;}
 [MenuItem("Editor/Digital Kingdom/Crear escena del reino",false,2032)]public static void BuildScene(){
  string path="Assets/Scenes/DigitalKingdom.unity";if(AssetDatabase.LoadAssetAtPath<SceneAsset>(path)!=null)return;
  var current=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var scene=UnityEditor.SceneManagement.EditorSceneManager.NewScene(UnityEditor.SceneManagement.NewSceneSetup.EmptyScene,UnityEditor.SceneManagement.NewSceneMode.Additive);UnityEngine.SceneManagement.SceneManager.SetActiveScene(scene);
  var root=new GameObject("Digital Kingdom — 2D Hub");var host=root.AddComponent<DungeonPrototype>();host.enabled=false;host.digitalKingdomSettings=DigitalKingdomSettings.Current;var controller=root.AddComponent<DigitalKingdomController>();controller.stateHost=host;
  var camera=new GameObject("City Camera").AddComponent<Camera>();camera.tag="MainCamera";camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;camera.cullingMask=0;camera.gameObject.AddComponent<AudioListener>();controller.cityCamera=camera;
  var light=new GameObject("City light — disabled for 2D").AddComponent<Light>();light.type=LightType.Directional;light.enabled=false;
  UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene,path);UnityEditor.SceneManagement.EditorSceneManager.CloseScene(scene,true);UnityEngine.SceneManagement.SceneManager.SetActiveScene(current);
  var scenes=new List<EditorBuildSettingsScene>(EditorBuildSettings.scenes);if(!scenes.Exists(s=>s.path==DigitalKingdomSettings.Current.fallbackDungeonScene))scenes.Add(new EditorBuildSettingsScene(DigitalKingdomSettings.Current.fallbackDungeonScene,true));scenes.Add(new EditorBuildSettingsScene(path,true));EditorBuildSettings.scenes=scenes.ToArray();AssetDatabase.SaveAssets();
 }
 [MenuItem("Editor/Digital Kingdom/Crear estructura inicial",false,2031)]public static void Build(){
  string root="Assets/Resources/DigitalKingdom";if(!AssetDatabase.IsValidFolder(root))AssetDatabase.CreateFolder("Assets/Resources","DigitalKingdom");if(!AssetDatabase.IsValidFolder(root+"/Locations"))AssetDatabase.CreateFolder(root,"Locations");
  var city=AssetDatabase.LoadAssetAtPath<DigitalKingdomSettings>(root+"/City.asset");if(city==null){city=ScriptableObject.CreateInstance<DigitalKingdomSettings>();AssetDatabase.CreateAsset(city,root+"/City.asset");}
  city.panorama=AssetDatabase.LoadAssetAtPath<Texture2D>(root+"/Panorama.png");
  string[] names={"The Last Life — Inn","Pay 2 Win — Item Shop","Temple of Continue — Save & Respawn","Bug Lab — Research Center","Fast Travel Station — Teleport Network","RNG Sewers — Procedural Dungeon","Exit City — Return to Dungeon"};
  string[] ids={"city.inn","city.shop","city.temple","city.lab","city.travel","city.sewers","city.exit"};string[] npcs={"INNKEEPER","SHOPKEEPER","PRIEST","SCIENTIST","OPERATOR","SEWER KEEPER",""};
  string[][] texts={new[]{"Welcome to The Last Life!","Heroes, villains, and background characters. Everyone needs a break.","Do you have a room?","Of course! Just don't ask about the previous guests.","...What happened to them?","Game over."},new[]{"Welcome to Pay 2 Win!","Everything you need to become a legendary hero!","Isn't that cheating?","Not if you can afford it."},new[]{"Welcome, lost player.","Even death is temporary for those who still have a Continue.","So... I can respawn here?","Provided the system remembers you.","That's... not very reassuring."},new[]{"Welcome to Bug Lab!","We don't fix bugs here.","Then what do you do?","We make them useful!"},new[]{"Welcome to Fast Travel Station.","Connecting worlds since version 1.0.","Is it safe?","Define safe."},new[]{"Welcome to the RNG Sewers.","No two trips are ever the same.","What's down there?","Depends on your luck.","And if I have bad luck?","Then you'll fit right in."},new string[0]};
  city.locations=new DigitalKingdomLocation[7];for(int i=0;i<7;i++){string path=root+"/Locations/0"+(i+1)+"-"+ids[i]+".asset";var l=AssetDatabase.LoadAssetAtPath<DigitalKingdomLocation>(path);if(l==null){l=ScriptableObject.CreateInstance<DigitalKingdomLocation>();AssetDatabase.CreateAsset(l,path);}l.id=ids[i];l.displayName=names[i];l.npcName=npcs[i];l.service=(DigitalKingdomService)i;l.dialogue=new WorldDialogueLine[texts[i].Length];for(int j=0;j<texts[i].Length;j++)l.dialogue[j]=new WorldDialogueLine(j==2||j==4?"GAMERBOY":npcs[i],texts[i][j]);var refuge=RefugeSettings.Current;if(refuge!=null&&refuge.npcs.Length>0)l.npcPortrait=refuge.npcs[i%refuge.npcs.Length].portrait;city.locations[i]=l;EditorUtility.SetDirty(l);}
  var inventory=Resources.Load<CombatInventorySettings>("Combat/CombatInventorySettings");var stock=new List<string>();foreach(var item in inventory.items)if(!item.keyItem&&item.healHP>0&&stock.Count<3)stock.Add(item.id);city.locations[1].stockIds=stock.ToArray();
  var map=DungeonMapSettings.Current;var regions=DungeonRegionSettings.Current;var boss=Array.Find(regions.placedEnemies,e=>e.id==city.requiredBossId);if(boss==null)throw new Exception("No se encontró Makong.");int x=boss.cell.x;
  if(map.rows.Length==56){System.IO.Directory.CreateDirectory("Backups/DigitalKingdom");System.IO.File.WriteAllText("Backups/DigitalKingdom/Map-before-city.json",JsonUtility.ToJson(map,true));System.IO.File.WriteAllText("Backups/DigitalKingdom/Regions-before-city.json",JsonUtility.ToJson(regions,true));Undo.RecordObjects(new UnityEngine.Object[]{map,regions,map.entities},"Añadir pasillo de salida hacia Digital Kingdom");var rows=new List<string>(map.rows);var last=rows[55].ToCharArray();last[x]='.';rows[55]=new string(last);while(rows.Count<69){var row=new string('#',map.rows[0].Length).ToCharArray();if(rows.Count<68)row[x]='.';rows.Add(new string(row));}map.rows=rows.ToArray();var zone=new DungeonRegion{id="zone-city-approach",displayName="Salida hacia Digital Kingdom",safeArea=true,spawnsEnabled=false,editorColor=Color.white};for(int y=55;y<=67;y++)zone.cells.Add(new Vector2Int(x,y));var zones=new List<DungeonRegion>(regions.regions);zones.Add(zone);regions.regions=zones.ToArray();EditorUtility.SetDirty(map);EditorUtility.SetDirty(regions);}
  var entry=map.entities.objects.Find(e=>e.id=="city.entrance");if(entry==null){entry=new DungeonMapEntity{id="city.entrance",displayName="Digital Kingdom",kind=DungeonEntityKind.Door,doorKind=DungeonDoorKind.Transition,cityEntrance=true,cell=new Vector2Int(x,66),heading=0};map.entities.objects.Add(entry);EditorUtility.SetDirty(map.entities);}city.fallbackReturnCell=new Vector2Int(x,65);city.fallbackReturnHeading=2;EditorUtility.SetDirty(city);AssetDatabase.SaveAssets();Selection.activeObject=city;
 }
}
